<template>
 <div class="ops-layout" :class="{ 'nav-collapsed': app.collapsed, 'mobile-open': mobileOpen, compact: app.compact }">
  <a class="skip-link" href="#main-content">跳至主要内容</a>
  <button v-if="mobileOpen" class="nav-backdrop" aria-label="关闭导航" @click="mobileOpen = false" />
  <aside class="layout-aside" aria-label="主导航">
   <router-link to="/dashboard" class="brand"><span class="brand-symbol"><svg viewBox="0 0 30 30" fill="none" aria-hidden="true"><path d="M8 9 5 3l8 3h4l8-3-3 6c4 4 4 11 0 15-4 3-10 3-14 0C4 20 4 13 8 9Z" stroke="currentColor" stroke-width="1.7"/><path d="M10 15h1m8 0h1m-8 5c2 2 4 2 6 0" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></span><span class="brand-copy"><b>毛团子<span>OPS</span></b><small>OPERATIONS CONSOLE</small></span></router-link>
   <button class="workspace" @click="searchOpen = true"><span class="workspace-avatar">M</span><span class="workspace-copy"><strong>毛团子 AI 工作区</strong><small>基础设施与业务运维</small></span><el-icon><ArrowDown /></el-icon></button>
   <div class="nav-search-wrap"><button class="nav-search" @click="searchOpen = true"><el-icon><Search /></el-icon><span>搜索工作台</span><kbd>⌘ K</kbd></button></div>
   <nav class="menu-scroll ops-scroll"><section v-for="group in groups" :key="group.title" class="nav-group"><div class="nav-label">{{ group.title }}</div><router-link v-for="item in group.items" :key="item.path" :to="item.path" class="nav-item" :class="{ active: activeMenu === item.path }" :title="item.title" :aria-current="activeMenu === item.path ? 'page' : undefined"><el-icon><component :is="item.icon" /></el-icon><span>{{ item.title }}</span><i v-if="activeMenu === item.path" class="active-dot" /></router-link></section></nav>
   <div class="aside-bottom"><div class="aside-status"><span class="status-dot" :class="contextError ? 'unknown' : context?.health?.status === 'UP' ? '' : 'warn'"/><span>{{ contextError ? '状态暂未获取' : context?.health?.status === 'UP' ? '服务运行正常' : context?.health?.status === 'DOWN' ? '服务需要关注' : '运行状态待确认' }}</span></div><small class="aside-version">OPS CONSOLE <span>v1.0.0</span></small></div>
  </aside>
  <div class="layout-content">
   <header class="layout-header"><div class="header-left"><button class="icon-button desktop-toggle" :aria-label="app.collapsed ? '展开导航' : '收起导航'" @click="app.toggleCollapsed()"><el-icon><component :is="app.collapsed ? 'Expand' : 'Fold'" /></el-icon></button><button class="icon-button mobile-toggle" aria-label="打开导航" @click="mobileOpen = true"><el-icon><Expand /></el-icon></button><span class="breadcrumb-root">控制台</span><span class="breadcrumb-separator">/</span><span class="breadcrumb-current">{{ currentTitle }}</span></div><div class="header-right"><span class="environment-badge"><span class="status-dot" :class="context?.app?.profile ? '' : 'unknown'" />{{ context?.app?.profile || '环境未采集' }}</span><span v-if="context?.app?.version" class="version-badge mono">v{{ context.app.version }}</span><span class="header-divider"/><el-tooltip :content="app.theme === 'dark' ? '切换浅色主题' : '切换深色主题'"><button class="icon-button" :aria-label="app.theme === 'dark' ? '切换浅色主题' : '切换深色主题'" @click="toggleTheme"><el-icon><component :is="app.theme === 'dark' ? 'Sunny' : 'Moon'" /></el-icon></button></el-tooltip><el-dropdown @command="onCommand"><button class="user-chip"><span class="user-avatar">{{ (user.nickname || user.username || 'U').charAt(0) }}</span><span class="user-copy"><b>{{ user.nickname || user.username }}</b><small>{{ user.isReadOnly ? '只读观察员' : '运维工作台' }}</small></span><el-icon><ArrowDown /></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item command="compact">{{ app.compact ? '舒适布局' : '紧凑布局' }}</el-dropdown-item><el-dropdown-item command="logout" divided>退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
   <main id="main-content" class="layout-main ops-scroll" tabindex="-1"><router-view v-slot="{ Component }"><transition name="fade" mode="out-in"><component :is="Component" /></transition></router-view><footer class="workspace-footer"><span>毛团子 AI · 企业运维工作台</span><span>Observe. Understand. Act.</span></footer></main>
  </div>
  <el-dialog v-model="searchOpen" title="快速导航" width="560px" align-center><el-input v-model="search" autofocus clearable placeholder="输入页面名称，如告警、日志、业务…" :prefix-icon="'Search'" aria-label="搜索页面"/><div class="search-results"><router-link v-for="item in searchResults" :key="item.path" :to="item.path" @click="searchOpen = false"><span><el-icon><component :is="item.icon" /></el-icon>{{ item.title }}</span><el-icon><Right /></el-icon></router-link><p v-if="!searchResults.length" class="empty-inline">没有匹配的页面</p></div><template #footer><span class="muted search-help">使用 Tab 选择页面，Enter 打开 · Esc 关闭</span></template></el-dialog>
 </div>
</template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useUserStore } from '@/stores/user'
import { useAppStore } from '@/stores/app'
import { ElMessageBox, ElMessage } from 'element-plus'
import * as ops from '@/api/ops'
const route = useRoute(), router = useRouter(), user = useUserStore(), app = useAppStore()
const mobileOpen = ref(false), searchOpen = ref(false), search = ref(''), context = ref<any>(null), contextError = ref(false)
interface MenuItem { path: string; title: string; icon: string; perm: string; group: string }
const allMenus: MenuItem[] = [
 {path:'/dashboard',title:'运维概览',icon:'Odometer',perm:'ops.view',group:'工作空间'},
 {path:'/biz/inspect',title:'业务巡检',icon:'DataAnalysis',perm:'ops.view',group:'工作空间'},
 {path:'/monitor/realtime',title:'实时监控',icon:'DataLine',perm:'ops.metrics',group:'可观测性'},
 {path:'/monitor/metrics',title:'指标趋势',icon:'TrendCharts',perm:'ops.metrics',group:'可观测性'},
 {path:'/logs',title:'日志中心',icon:'Document',perm:'ops.log',group:'可观测性'},
 {path:'/alarm/records',title:'告警记录',icon:'Bell',perm:'ops.alarm',group:'可观测性'},
 {path:'/alarm/rules',title:'告警规则',icon:'SetUp',perm:'ops.alarm',group:'可观测性'},
 {path:'/system/resource',title:'系统资源',icon:'Cpu',perm:'ops.system',group:'基础设施'},
 {path:'/system/threads',title:'线程快照',icon:'Collection',perm:'ops.system',group:'基础设施'},
 {path:'/instances',title:'服务实例',icon:'Monitor',perm:'ops.view',group:'基础设施'},
 {path:'/datasource/db',title:'数据库',icon:'Coin',perm:'ops.datasource',group:'基础设施'},
 {path:'/datasource/redis',title:'Redis 缓存',icon:'Connection',perm:'ops.datasource',group:'基础设施'},
 {path:'/storage',title:'存储空间',icon:'FolderOpened',perm:'ops.storage',group:'基础设施'},
 {path:'/job/list',title:'任务调度',icon:'Timer',perm:'ops.job',group:'治理与配置'},
 {path:'/job/records',title:'执行记录',icon:'List',perm:'ops.job',group:'治理与配置'},
 {path:'/audit/admin',title:'管理审计',icon:'Stamp',perm:'ops.audit',group:'治理与配置'},
 {path:'/audit/content',title:'内容审计',icon:'DocumentChecked',perm:'ops.audit',group:'治理与配置'},
 {path:'/config',title:'运维配置',icon:'Setting',perm:'ops.config',group:'治理与配置'}
]
const menus = computed(() => allMenus.filter(m => user.hasPerm(m.perm)))
const groups = computed(() => ['工作空间','可观测性','基础设施','治理与配置'].map(title => ({title,items:menus.value.filter(m => m.group === title)})).filter(g => g.items.length))
const searchResults = computed(() => menus.value.filter(m => `${m.title} ${m.group}`.includes(search.value.trim())))
const activeMenu = computed(() => route.path)
const currentTitle = computed(() => allMenus.find(m => m.path === route.path)?.title || String(route.meta.title || '工作台'))
function toggleTheme() { app.setTheme(app.theme === 'dark' ? 'light' : 'dark') }
async function onCommand(cmd: string) {
 if (cmd === 'compact') { app.setCompact(!app.compact); return }
 if (cmd !== 'logout') return
 try { await ElMessageBox.confirm('退出后需要重新验证身份。确认退出当前工作台？','退出登录',{confirmButtonText:'退出登录',cancelButtonText:'继续工作',type:'warning'}) } catch { return }
 try { await user.logout(); ElMessage.success('已安全退出') } catch { ElMessage.info('本机登录已退出，服务端注销暂未确认') } finally { await router.replace('/login') }
}
function handleShortcut(event: KeyboardEvent) { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); searchOpen.value = !searchOpen.value } }
watch(() => route.fullPath, () => { mobileOpen.value = false })
onMounted(async () => { window.addEventListener('keydown',handleShortcut); if (!user.hasPerm('ops.view')) return; try { context.value = await ops.overview() } catch { contextError.value = true } })
onUnmounted(() => window.removeEventListener('keydown',handleShortcut))
</script>
